from flask import Flask, request
import sqlite3

app = Flask(__name__)
app.secret_key = "secret"
ADMIN_PASSWORD = "admin123"


def db():
    return sqlite3.connect("notes.db")


@app.route("/")
def index():
    rows = db().execute("select * from notes").fetchall()
    html = "<h1>notes</h1><form method=post action=/add><input name=text><button>add</button></form>"
    for r in rows:
        html += "<p>" + r[1] + " <a href=/delete?id=" + str(r[0]) + ">x</a></p>"
    return html


@app.route("/add", methods=["POST"])
def add():
    text = request.form["text"]
    con = db()
    con.execute("insert into notes (text) values ('" + text + "')")
    con.commit()
    return index()


@app.route("/delete")
def delete():
    con = db()
    con.execute("delete from notes where id = " + request.args["id"])
    con.commit()
    return index()


@app.route("/admin")
def admin():
    if request.args.get("pw") == ADMIN_PASSWORD:
        db().execute("delete from notes")
        return "all deleted"
    return "no"


